// Generated by vibes-espmatter – login, sessions and users of the HTTP server (web interface, OTA).
//
// All accounts – admins and users – live in NVS. The build configuration (HTTP server →
// initial admin login) only seeds the first admin: on first boot, and whenever the configured
// initial login changes, that admin is (re)created with the initial password, which must be
// changed at the first login. Users (not admins) may only use what routes allow them.
// Passwords are stored as salted PBKDF2-SHA256 hashes. Sessions are random tokens in an HttpOnly
// cookie and survive reboots (NVS).
//
// The device may be reachable from the internet (through an HTTPS reverse proxy), so wrong
// passwords – login form and HTTP Basic auth alike – lock all password checks for a while once
// there were LOCK_AFTER in a row, doubling up to LOCK_MAX_S. Logged-in sessions keep working.
#include "espm_config.h"
#include "espm_web.h"

#include <algorithm>
#include <cctype>
#include <cstring>
#include <esp_log.h>
#include <esp_random.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <freertos/task.h>
#include <mbedtls/base64.h>
#include <mbedtls/md.h>
#include <mbedtls/pkcs5.h>
#include <nvs.h>
#include <strings.h>

static const char *TAG = "mesp_auth";

#define MAX_USERS 10
#define MAX_REMOVED_LISTENERS 4
#define MAX_SESSIONS 16
#define MIN_PASSWORD 6
#define PBKDF2_ITERATIONS 2000
#define COOKIE "mesp_session"
/** Wrong passwords in a row before password checks are locked. */
#define LOCK_AFTER 5
/** First lock 30 s, doubling with every further wrong password, at most 15 min. */
#define LOCK_FIRST_S 30
#define LOCK_MAX_S 900

#define FLAG_MUST_CHANGE 0x01

// Layout is stored in NVS as is – only append, never reorder. The endpoints a user may use are the
// Matter controller's (espm_matter_access.cpp).
struct user_t {
    char name[24];
    uint8_t salt[16];
    uint8_t hash[32];
    uint8_t role;
    uint8_t flags;
    uint8_t reserved[6];
};

struct session_rec_t {
    char token[65]; // 32 random bytes as hex; the role is taken from the user
    char user[24];
    uint32_t seq; // for evicting the oldest session
};

static user_t s_users[MAX_USERS];
static size_t s_user_count = 0;
static session_rec_t s_sessions[MAX_SESSIONS];
static uint32_t s_seq = 0;
static SemaphoreHandle_t s_mutex;
static void (*s_removed[MAX_REMOVED_LISTENERS])(const char *user);

namespace {
struct Lock {
    Lock() { xSemaphoreTakeRecursive(s_mutex, portMAX_DELAY); }
    ~Lock() { xSemaphoreGiveRecursive(s_mutex); }
};
} // namespace

static mesp_role_t role_of(const user_t &u)
{
    return u.role == MESP_ROLE_ADMIN ? MESP_ROLE_ADMIN : MESP_ROLE_USER;
}

// ---------------------------------------------------------------------------------------------
// Storage
// ---------------------------------------------------------------------------------------------

static void save(const char *key, const void *data, size_t len)
{
    nvs_handle_t h;
    if (nvs_open("mesp_auth", NVS_READWRITE, &h) != ESP_OK) return;
    nvs_set_blob(h, key, data, len);
    nvs_commit(h);
    nvs_close(h);
}

static void users_save() { save("users", s_users, s_user_count * sizeof(user_t)); }
static void sessions_save() { save("sessions", s_sessions, sizeof(s_sessions)); }

// ---------------------------------------------------------------------------------------------
// Passwords and sessions
// ---------------------------------------------------------------------------------------------

static bool equal(const void *a, const void *b, size_t len)
{
    // Constant time: don't leak how much of a secret matched.
    const uint8_t *x = (const uint8_t *)a, *y = (const uint8_t *)b;
    uint8_t diff = 0;
    for (size_t i = 0; i < len; i++) diff |= x[i] ^ y[i];
    return diff == 0;
}

static void hash_password(const std::string &password, const uint8_t salt[16], uint8_t out[32])
{
    mbedtls_pkcs5_pbkdf2_hmac_ext(MBEDTLS_MD_SHA256, (const unsigned char *)password.data(), password.size(), salt, 16,
                                  PBKDF2_ITERATIONS, 32, out);
}

static void set_password(user_t &u, const std::string &password)
{
    esp_fill_random(u.salt, sizeof(u.salt));
    hash_password(password, u.salt, u.hash);
}

static bool check_password(const user_t &u, const std::string &password)
{
    uint8_t hash[32];
    hash_password(password, u.salt, hash);
    return equal(hash, u.hash, 32);
}

static int user_index(const char *name)
{
    for (size_t i = 0; i < s_user_count; i++)
        if (strcmp(s_users[i].name, name) == 0) return i;
    return -1;
}

static size_t admin_count()
{
    size_t n = 0;
    for (size_t i = 0; i < s_user_count; i++)
        if (role_of(s_users[i]) == MESP_ROLE_ADMIN) n++;
    return n;
}

static session_rec_t *find_session(const char *token)
{
    if (strlen(token) != 64) return nullptr;
    for (auto &s : s_sessions)
        if (s.token[0] && equal(s.token, token, 64)) return &s;
    return nullptr;
}

static const session_rec_t &create_session(const char *user)
{
    session_rec_t *slot = &s_sessions[0];
    for (auto &s : s_sessions) {
        if (!s.token[0]) {
            slot = &s;
            break;
        }
        if (s.seq < slot->seq) slot = &s; // evict the oldest
    }
    uint8_t random[32];
    esp_fill_random(random, sizeof(random));
    for (int i = 0; i < 32; i++) snprintf(&slot->token[i * 2], 3, "%02x", random[i]);
    strlcpy(slot->user, user, sizeof(slot->user));
    slot->seq = ++s_seq;
    sessions_save();
    return *slot;
}

static void drop_sessions_of(const char *user)
{
    for (auto &s : s_sessions)
        if (s.token[0] && strcmp(s.user, user) == 0) memset(&s, 0, sizeof(s));
    sessions_save();
}

/**
 * Create the configured admin on first boot, and reset it whenever the initial login in the build
 * configuration changes (`MESP_WEB_AUTH_SEED`) – that's also how a forgotten password is recovered.
 */
static void seed_admin()
{
    uint32_t seed = 0;
    nvs_handle_t h;
    if (nvs_open("mesp_auth", NVS_READONLY, &h) == ESP_OK) {
        nvs_get_u32(h, "seed", &seed);
        nvs_close(h);
    }
    int idx = user_index(MESP_WEB_AUTH_USER);
    if (seed == (uint32_t)MESP_WEB_AUTH_SEED && admin_count() > 0) return;

    if (idx < 0) {
        if (s_user_count >= MAX_USERS) s_user_count--; // make room: drop the newest user
        idx = s_user_count++;
        memset(&s_users[idx], 0, sizeof(user_t));
        strlcpy(s_users[idx].name, MESP_WEB_AUTH_USER, sizeof(s_users[idx].name));
    }
    user_t &u = s_users[idx];
    u.role = MESP_ROLE_ADMIN;
    u.flags |= FLAG_MUST_CHANGE;
    set_password(u, MESP_WEB_AUTH_PASSWORD);
    drop_sessions_of(u.name);
    users_save();
    if (nvs_open("mesp_auth", NVS_READWRITE, &h) == ESP_OK) {
        nvs_set_u32(h, "seed", (uint32_t)MESP_WEB_AUTH_SEED);
        nvs_commit(h);
        nvs_close(h);
    }
    ESP_LOGI(TAG, "admin '%s' set to the initial password from the build configuration", u.name);
}

void mesp_auth_init()
{
    s_mutex = xSemaphoreCreateRecursiveMutex();
    nvs_handle_t h;
    if (nvs_open("mesp_auth", NVS_READONLY, &h) == ESP_OK) {
        size_t len = sizeof(s_users);
        if (nvs_get_blob(h, "users", s_users, &len) == ESP_OK) s_user_count = len / sizeof(user_t);
        len = sizeof(s_sessions);
        if (nvs_get_blob(h, "sessions", s_sessions, &len) != ESP_OK || len != sizeof(s_sessions)) {
            memset(s_sessions, 0, sizeof(s_sessions));
        }
        nvs_close(h);
    }
    for (const auto &s : s_sessions)
        if (s.seq > s_seq) s_seq = s.seq;
    seed_admin();
    ESP_LOGI(TAG, "%u users (%u admins)", (unsigned)s_user_count, (unsigned)admin_count());
}

// ---------------------------------------------------------------------------------------------
// Guessing protection (all under the lock)
// ---------------------------------------------------------------------------------------------

static uint32_t s_failures;
static int64_t s_locked_until;

/** Seconds until passwords are checked again; 0 = now. */
static uint32_t locked_for()
{
    const int64_t left = s_locked_until - esp_timer_get_time();
    return left > 0 ? (uint32_t)((left + 999999) / 1000000) : 0;
}

/** Check a password unless locked, and count the result. */
static bool try_password(int idx, const std::string &password)
{
    if (locked_for()) return false;
    if (idx >= 0 && check_password(s_users[idx], password)) {
        s_failures = 0;
        return true;
    }
    if (++s_failures >= LOCK_AFTER) {
        const uint32_t shift = s_failures - LOCK_AFTER;
        const uint32_t secs = shift >= 5 ? LOCK_MAX_S : std::min<uint32_t>(LOCK_FIRST_S << shift, LOCK_MAX_S);
        s_locked_until = esp_timer_get_time() + (int64_t)secs * 1000000;
        ESP_LOGW(TAG, "%u wrong passwords in a row: logins locked for %u s", (unsigned)s_failures, (unsigned)secs);
    }
    return false;
}

static mesp_session_t session_of(const user_t &u)
{
    mesp_session_t s = {role_of(u), "", (u.flags & FLAG_MUST_CHANGE) != 0};
    strlcpy(s.user, u.name, sizeof(s.user));
    return s;
}

mesp_session_t mesp_web_session(httpd_req_t *req)
{
    mesp_session_t out = {MESP_ROLE_NONE, "", false};
    // HTTP Basic auth, for tools (OTA from the vibes-espmatter app). Admins only.
    char header[160] = {0};
    if (httpd_req_get_hdr_value_str(req, "Authorization", header, sizeof(header)) == ESP_OK &&
        strncmp(header, "Basic ", 6) == 0) {
        unsigned char pair[120];
        size_t len = 0;
        if (mbedtls_base64_decode(pair, sizeof(pair) - 1, &len, (const unsigned char *)header + 6,
                                  strlen(header + 6)) == 0) {
            pair[len] = 0;
            char *colon = strchr((char *)pair, ':');
            if (colon) {
                *colon = 0;
                Lock lock;
                int idx = user_index((char *)pair);
                if (try_password(idx, colon + 1) && role_of(s_users[idx]) == MESP_ROLE_ADMIN) {
                    out = session_of(s_users[idx]);
                    out.must_change = false; // tools can't change it; the login page will ask
                }
            }
        }
        return out;
    }
    char token[80] = {0};
    size_t len = sizeof(token);
    if (httpd_req_get_cookie_val(req, COOKIE, token, &len) != ESP_OK) return out;
    Lock lock;
    const session_rec_t *s = find_session(token);
    // Sessions end when the user is deleted; role changes apply immediately.
    int idx = s ? user_index(s->user) : -1;
    if (idx >= 0) out = session_of(s_users[idx]);
    return out;
}

void mesp_web_on_user_removed(void (*fn)(const char *user))
{
    for (auto &slot : s_removed) {
        if (!slot) {
            slot = fn;
            return;
        }
    }
    ESP_LOGE(TAG, "too many user-removed listeners");
}

// ---------------------------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------------------------

static void set_cookie(httpd_req_t *req, const char *token, bool clear)
{
    // The header value must stay valid until the response is sent.
    static char cookie[170];
    // Behind an HTTPS reverse proxy the cookie must never go over plain HTTP.
    char proto[8] = {0};
    const bool https = httpd_req_get_hdr_value_str(req, "X-Forwarded-Proto", proto, sizeof(proto)) == ESP_OK &&
                       strcasecmp(proto, "https") == 0;
    snprintf(cookie, sizeof(cookie), COOKIE "=%s; Path=/; HttpOnly; SameSite=Strict; Max-Age=%d%s", token,
             clear ? 0 : 365 * 24 * 3600, https ? "; Secure" : "");
    httpd_resp_set_hdr(req, "Set-Cookie", cookie);
}

static const char *role_name(mesp_role_t role)
{
    return role == MESP_ROLE_ADMIN ? "admin" : role == MESP_ROLE_USER ? "user" : "none";
}

static esp_err_t send_me(httpd_req_t *req, const mesp_session_t &s)
{
    Json j;
    j.obj().key("authenticated").boolean(s.role != MESP_ROLE_NONE).key("user").str(s.user);
    j.key("role").str(role_name(s.role));
    j.key("mustChangePassword").boolean(s.must_change);
    j.key("authEnabled").boolean(true).end_obj();
    return mesp_web_send_json(req, j.out());
}

static esp_err_t me_handler(httpd_req_t *req)
{
    return send_me(req, mesp_web_session(req));
}

static esp_err_t login_handler(httpd_req_t *req)
{
    std::string body, user, password;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "user", user);
    mesp_web_param(body, "password", password);

    mesp_session_t s = {MESP_ROLE_NONE, "", false};
    uint32_t locked;
    {
        Lock lock;
        locked = locked_for();
        int idx = user_index(user.c_str());
        if (!locked && try_password(idx, password)) {
            s = session_of(s_users[idx]);
            set_cookie(req, create_session(s.user).token, false);
        }
    }
    if (locked) {
        char msg[80];
        snprintf(msg, sizeof(msg), "too many wrong passwords – try again in %u s", (unsigned)locked);
        return mesp_web_send_error(req, "429 Too Many Requests", msg);
    }
    if (s.role == MESP_ROLE_NONE) {
        vTaskDelay(pdMS_TO_TICKS(600)); // slow down guessing
        return mesp_web_send_error(req, "401 Unauthorized", "wrong user name or password");
    }
    ESP_LOGI(TAG, "%s logged in (%s)", s.user, role_name(s.role));
    return send_me(req, s);
}

static esp_err_t logout_handler(httpd_req_t *req)
{
    char token[80] = {0};
    size_t len = sizeof(token);
    if (httpd_req_get_cookie_val(req, COOKIE, token, &len) == ESP_OK) {
        Lock lock;
        session_rec_t *s = find_session(token);
        if (s) {
            memset(s, 0, sizeof(*s));
            sessions_save();
        }
    }
    set_cookie(req, "", true);
    return mesp_web_send_json(req, "{\"ok\":true}");
}

/** Change your own password (also the forced change after the first login). */
static esp_err_t password_handler(httpd_req_t *req)
{
    mesp_session_t s = mesp_web_session(req);
    if (s.role == MESP_ROLE_NONE) return mesp_web_send_error(req, "401 Unauthorized", "please log in");
    std::string body, current, password;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "current", current);
    mesp_web_param(body, "password", password);

    Lock lock;
    int idx = user_index(s.user);
    if (idx < 0) return mesp_web_send_error(req, "401 Unauthorized", "please log in");
    user_t &u = s_users[idx];
    if (!check_password(u, current)) {
        vTaskDelay(pdMS_TO_TICKS(600));
        return mesp_web_send_error(req, "403 Forbidden", "current password is wrong");
    }
    if (password.size() < MIN_PASSWORD) {
        return mesp_web_send_error(req, "400 Bad Request", "password: at least 6 characters");
    }
    if (password == current) return mesp_web_send_error(req, "400 Bad Request", "choose a new password");
    set_password(u, password);
    u.flags &= ~FLAG_MUST_CHANGE;
    users_save();
    drop_sessions_of(u.name); // log out everywhere else …
    set_cookie(req, create_session(u.name).token, false); // … but stay logged in here
    ESP_LOGI(TAG, "%s changed their password", u.name);
    return send_me(req, session_of(u));
}

static esp_err_t users_get(httpd_req_t *req)
{
    mesp_session_t me;
    if (!mesp_web_require(req, MESP_ROLE_ADMIN, &me)) return ESP_OK;
    Json j;
    {
        Lock lock;
        j.obj().key("me").str(me.user);
        j.key("max").num(MAX_USERS).key("users").arr();
        for (size_t i = 0; i < s_user_count; i++) {
            const user_t &u = s_users[i];
            j.obj().key("name").str(u.name).key("role").str(role_name(role_of(u)));
            j.key("mustChangePassword").boolean(u.flags & FLAG_MUST_CHANGE).end_obj();
        }
        j.end_arr().end_obj();
    }
    return mesp_web_send_json(req, j.out());
}

static bool valid_name(const std::string &name)
{
    if (name.empty() || name.size() >= sizeof(user_t::name)) return false;
    for (char c : name)
        if (!(isalnum((unsigned char)c) || c == '-' || c == '_' || c == '.')) return false;
    return true;
}

static bool parse_role(const std::string &value, uint8_t &role)
{
    if (value == "admin") role = MESP_ROLE_ADMIN;
    else if (value == "user") role = MESP_ROLE_USER;
    else return false;
    return true;
}

static esp_err_t users_post(httpd_req_t *req)
{
    mesp_session_t me;
    if (!mesp_web_require(req, MESP_ROLE_ADMIN, &me)) return ESP_OK;
    std::string body, op, name, password, role_str;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "op", op);
    mesp_web_param(body, "name", name);
    bool has_password = mesp_web_param(body, "password", password);
    bool has_role = mesp_web_param(body, "role", role_str);
    uint8_t role = MESP_ROLE_USER;
    if (has_role && !parse_role(role_str, role)) return mesp_web_send_error(req, "400 Bad Request", "unknown role");

    Lock lock;
    int idx = user_index(name.c_str());
    if (op == "add") {
        if (!valid_name(name)) {
            return mesp_web_send_error(req, "400 Bad Request", "user name: letters, digits, - _ . (max. 23)");
        }
        if (idx >= 0) return mesp_web_send_error(req, "409 Conflict", "user exists already");
        if (s_user_count >= MAX_USERS) return mesp_web_send_error(req, "409 Conflict", "too many users");
        if (password.size() < MIN_PASSWORD) {
            return mesp_web_send_error(req, "400 Bad Request", "password: at least 6 characters");
        }
        user_t u = {};
        strlcpy(u.name, name.c_str(), sizeof(u.name));
        u.role = role;
        u.flags = FLAG_MUST_CHANGE; // the admin picked it – the user chooses their own
        set_password(u, password);
        s_users[s_user_count++] = u;
    } else if (op == "set") {
        if (idx < 0) return mesp_web_send_error(req, "404 Not Found", "unknown user");
        user_t &u = s_users[idx];
        if (has_role && role != MESP_ROLE_ADMIN && role_of(u) == MESP_ROLE_ADMIN && admin_count() <= 1) {
            return mesp_web_send_error(req, "409 Conflict", "the last admin can't become a user");
        }
        if (has_role) u.role = role;
        if (has_password) {
            if (password.size() < MIN_PASSWORD) {
                return mesp_web_send_error(req, "400 Bad Request", "password: at least 6 characters");
            }
            set_password(u, password);
            u.flags |= FLAG_MUST_CHANGE;
            drop_sessions_of(u.name); // log out everywhere
        }
    } else if (op == "delete") {
        if (idx < 0) return mesp_web_send_error(req, "404 Not Found", "unknown user");
        if (strcmp(s_users[idx].name, me.user) == 0) {
            return mesp_web_send_error(req, "409 Conflict", "you can't delete yourself");
        }
        if (role_of(s_users[idx]) == MESP_ROLE_ADMIN && admin_count() <= 1) {
            return mesp_web_send_error(req, "409 Conflict", "the last admin can't be deleted");
        }
        drop_sessions_of(s_users[idx].name);
        for (auto fn : s_removed)
            if (fn) fn(s_users[idx].name);
        for (size_t i = idx; i + 1 < s_user_count; i++) s_users[i] = s_users[i + 1];
        s_user_count--;
    } else {
        return mesp_web_send_error(req, "400 Bad Request", "unknown op");
    }
    users_save();
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_auth_register_routes()
{
    mesp_web_add("/api/auth/me", HTTP_GET, me_handler);
    mesp_web_add("/api/auth/login", HTTP_POST, login_handler);
    mesp_web_add("/api/auth/logout", HTTP_POST, logout_handler);
    mesp_web_add("/api/auth/password", HTTP_POST, password_handler);
    mesp_web_add("/api/users", HTTP_GET, users_get);
    mesp_web_add("/api/users", HTTP_POST, users_post);
}
